(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  function setVal(el, v) {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(el, v);
    el.dispatchEvent(new Event('input', {bubbles:true}));
    el.dispatchEvent(new Event('change', {bubbles:true}));
  }
  const boxes = Array.from(document.querySelectorAll('input[type=number]')).filter(i=>i.offsetParent!==null && /^(first|second|third|fourth|fifth|sixth)$/.test(i.id||''));
  if (!boxes.length) return JSON.stringify({stage:'noBoxes', url: location.href});
  const digits = '664407';
  for (let i=0;i<boxes.length;i++) setVal(boxes[i], i < digits.length ? digits[i] : '');
  await sleep(400);
  const cfm = Array.from(document.querySelectorAll('button')).find(b => /confirm\s*otp/i.test((b.innerText||'').replace(/\s+/g,' ')) && b.offsetParent!==null);
  if (cfm) cfm.click();
  await sleep(10000);
  return JSON.stringify({
    url: location.href,
    visBtns: Array.from(document.querySelectorAll('button')).filter(b=>b.offsetParent!==null).map(b=>(b.innerText||'').replace(/\s+/g,' ').trim()).filter(Boolean).filter(t=>/login|confirm|otp|send|web|trader|try|continue/i.test(t)).slice(0,8),
    errs: (Array.from(document.querySelectorAll('div,span,p,label')).map(e=>(e.innerText||'').replace(/\s+/g,' ').trim()).filter(t=>/wrong|invalid|incorrect|expired|failed|mismatch/i.test(t) && t.length<100).slice(0,3)),
    txt: (document.body.innerText||'').replace(/\s+/g,' ').slice(0,300)
  });
})()
